<?php require __DIR__.'/../includes/auth.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([user()['id']]);flash('success','Notifications marked as read.');header('Location: notifications.php');exit;}$s=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$s->execute([user()['id']]);$rows=$s->fetchAll();$pageTitle='Notifications';require __DIR__.'/../includes/header.php';?><div class="section-head"><h1>Notifications</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="small">Mark all read</button></form></div><?php foreach($rows as $n):?><article class="panel"><b><?=e($n['title'])?></b><p><?=e($n['message'])?></p><span class="muted"><?=e($n['created_at'])?> · <?=e($n['type'])?></span></article><?php endforeach;?><?php require __DIR__.'/../includes/footer.php'; ?>
